CREATE TABLE public.blog_posts (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  meta_description TEXT NOT NULL,
  excerpt TEXT NOT NULL,
  content TEXT NOT NULL,
  keyword TEXT,
  published BOOLEAN NOT NULL DEFAULT true,
  published_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);
GRANT SELECT ON public.blog_posts TO anon;
GRANT SELECT ON public.blog_posts TO authenticated;
GRANT ALL ON public.blog_posts TO service_role;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can read published posts" ON public.blog_posts FOR SELECT TO anon, authenticated USING (published = true);

INSERT INTO public.blog_posts (slug, title, meta_description, excerpt, content, keyword) VALUES
('cum-alegi-etichetele-textile-potrivite', 'Cum alegi etichetele textile potrivite pentru produsele tale', 'Ghid practic: cum alegi etichetele textile potrivite — țesute, satin sau imprimate — în funcție de țesătură, spălare și buget. Sfaturi de la un producător cu experiență din 1993.', 'Alegerea etichetei textile potrivite influențează atât aspectul produsului, cât și rezistența în timp. Iată criteriile esențiale pe care le recomandăm după peste 30 de ani de producție.', '<h2>De ce contează eticheta textile</h2><p>Eticheta este primul element pe care clientul îl atinge și, adesea, singurul care rămâne pe produs după ani de utilizare. O etichetă de calitate transmite profesionalism și crește valoarea percepută a articolului vestimentar.</p><h2>1. În funcție de țesătură</h2><p>Pentru haine din bumbac sau lenjerie, etichetele din <strong>satin</strong> sunt cele mai delicate la contactul cu pielea. Pentru articole premium — paltoane, costume, branduri de lux — etichetele <strong>țesute (jacquard)</strong> oferă un aspect nobil și o durabilitate excepțională. Pentru echipamente sport și produse tehnice, etichetele imprimate pe <strong>nylon sau poliester</strong> rezistă cel mai bine la spălări frecvente.</p><h2>2. În funcție de regimul de spălare</h2><p>Dacă produsul se spală la temperaturi mari (60–90°C) sau se curăță chimic, alege etichete imprimate cu cerneală rezistentă sau țesute. Etichetele termoadezive sunt ideale pentru aplicații rapide, dar verifică întotdeauna compatibilitatea cu țesătura.</p><h2>3. În funcție de informațiile obligatorii</h2><p>Legislația UE cere ca eticheta de compoziție să indice procentele fibrelor, țara de origine și simbolurile de întreținere (ISO 3758). Planifică din timp spațiul necesar: o etichetă prea mică cu text prea dens devine ilizibilă.</p><h2>4. Buget și tiraj</h2><p>Etichetele țesute au un cost fix de pregătire, dar devin foarte accesibile la tiraje mari. Etichetele imprimate sunt economice chiar și la câteva sute de bucăți — perfecte pentru branduri la început de drum.</p><h2>Concluzie</h2><p>Nu există o etichetă universal bună — există eticheta potrivită pentru produsul tău. Trimite-ne o mostră din țesătură și îți recomandăm gratuit varianta optimă.</p>', 'etichete textile'),
('simboluri-spalare-etichete-ghid', 'Simbolurile de spălare de pe etichete: ghid complet pentru producători', 'Ce înseamnă simbolurile de întreținere de pe etichetele textile (ISO 3758) și cum le folosești corect pe etichetele de compoziție. Ghid complet pentru producătorii de îmbrăcăminte.', 'Simbolurile de întreținere sunt obligatorii pe etichetele de compoziție. Greșelile costă: retururi, reclamații și produse distruse. Află cum le folosești corect.', '<h2>Ce sunt simbolurile de întreținere</h2><p>Standardul internațional ISO 3758 definește cinci categorii de simboluri, în această ordine obligatorie: <strong>spălare, înălbire, uscare, călcare, curățare profesională</strong>.</p><h2>1. Spălarea (ligheanul)</h2><p>Cifra din lighean indică temperatura maximă în grade Celsius. O linie sub lighean înseamnă program delicat; două linii — program foarte delicat. Mâna în lighean = doar spălare manuală. Ligheanul tăiat = nu se spală în apă.</p><h2>2. Înălbirea (triunghiul)</h2><p>Triunghiul gol permite înălbirea cu clor; triunghiul cu linii diagonale permite doar înălbitori fără clor (pe bază de oxigen); triunghiul tăiat interzice orice înălbitor.</p><h2>3. Uscarea (pătratul)</h2><p>Cercul în pătrat = uscare în uscătorul automat (punctele indică temperatura). Liniile din pătrat indică uscarea naturală: verticală, orizontală, la umbră.</p><h2>4. Călcarea (fierul)</h2><p>Punctele din fier indică temperatura maximă: un punct 110°C, două 150°C, trei 200°C. Fierul tăiat = nu se calcă.</p><h2>5. Curățarea profesională (cercul)</h2><p>Litera din cerc (P, F, W) indică solventul permis pentru curățarea chimică. Cercul tăiat = nu se curăță chimic.</p><h2>Sfaturi practice pentru producători</h2><p>Testează întotdeauna țesătura finită, nu doar fibra brută — vopsirea și finisajele pot schimba comportamentul la spălare. Tipărește simbolurile la o dimensiune lizibilă (minim 4–5 mm) și păstrează ordinea standard. La Etichett Prod tipărim etichete de compoziție cu toate simbolurile ISO 3758, în orice combinație.</p>', 'simboluri etichete haine'),
('etichete-tesute-vs-imprimate', 'Etichete țesute sau imprimate? Comparație onestă pentru branduri', 'Etichete țesute vs imprimate: diferențe de aspect, durabilitate, cost și tiraj minim. Comparație detaliată care te ajută să alegi corect pentru brandul tău de îmbrăcăminte.', 'Două tehnologii, două filosofii. Etichetele țesute și cele imprimate au fiecare avantajele lor — iată comparația completă, fără părtinire, de la un producător care le face pe ambele.', '<h2>Aspect și percepție</h2><p>Etichetele <strong>țesute (jacquard)</strong> au textura și profunzimea firului împletit — logo-ul pare „sculptat” în material. Sunt standardul în segmentul premium. Etichetele <strong>imprimate</strong> oferă culori nelimitate, degradé-uri și detalii fine imposibil de țesut, cu un aspect curat și modern.</p><h2>Durabilitate</h2><p>O etichetă țesută de calitate rezistă cât produsul însuși — firul nu se decolorează și nu se șterge. Etichetele imprimate moderne (cu cerneală rezistentă pe satin sau poliester) suportă zeci de spălări, dar la regimuri agresive (spălări industriale, înălbitor) imprimeul poate estompa în timp.</p><h2>Cost și tiraj</h2><p>Țesutul implică un cost fix de pregătire a jacquardului, deci devine avantajos de la câteva sute de bucăți în sus — cu cât tirajul e mai mare, cu atât prețul pe bucată scade spectaculos. Imprimarea nu are costuri de pregătire semnificative: poți comanda economic chiar și 100 de bucăți, ideal pentru prototipuri și capsule collection.</p><h2>Timp de producție</h2><p>Etichetele imprimate se produc mai repede. Cele țesute necesită pregătirea modelului, dar la comenzi recurente (modelul există deja) termenele se scurtează considerabil.</p><h2>Recomandarea noastră</h2><p>Brand nou, tiraje mici, design colorat → imprimate. Brand consolidat, linie premium, tiraje medii și mari → țesute. Multe branduri folosesc ambele: etichetă țesută cu logo la gât și etichetă imprimată de compoziție la lateral. Trimite-ne designul și îți spunem pe loc care variantă ți se potrivește.</p>', 'etichete tesute');